// SPDX-License-Identifier: CC0-1.0
// 参考: https://nyaannyaan.github.io/library/set-function/zeta-mobius-transform.hpp.html
// Original Source: https://nyaannyaan.github.io/library/set-function/and-convolution.hpp.html
// Original Source: https://nyaannyaan.github.io/library/set-function/or-convolution.hpp.html
#include <bit>
#include <cstddef>
#include <cstring>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>

// 集合4変換: 空配列または長さn=2^kを直接更新、O(1+n log(n+1))時間・O(1)追加領域。
// superset_zeta_transform(f): f[S]を上位集合の総和へ更新、Tの+=が必要。
// superset_mobius_transform(f): 上位集合ゼータ変換の逆、Tの-=が必要。
// subset_zeta_transform(f): f[S]を部分集合の総和へ更新、Tの+=が必要。
// subset_mobius_transform(f): 部分集合ゼータ変換の逆、Tの-=が必要。
// Tはbool以外の加法型。符号付き整数の全途中結果は型の範囲内、符号なしは型の幅の剰余。値演算送出時は部分更新。
#ifndef SIRKIT_SET_TRANSFORM_SCALAR_DETAIL_DEFINED
#define SIRKIT_SET_TRANSFORM_SCALAR_DETAIL_DEFINED
namespace reinsirk::detail {
template <bool Subset, bool Subtract, class T>
inline void set_transform_scalar(std::vector<T>& f) {
    const std::size_t n = f.size();
    if (n >= 8) {
        for (std::size_t base = 0; base < n; base += 8) {
            auto add = [&](std::size_t a, std::size_t b) {
                if constexpr (Subtract) f[base + a] -= f[base + b];
                else f[base + a] += f[base + b];
            };
            if constexpr (Subset) {
                add(1, 0); add(3, 2); add(5, 4); add(7, 6);
                add(2, 0); add(3, 1); add(6, 4); add(7, 5);
                add(4, 0); add(5, 1); add(6, 2); add(7, 3);
            } else {
                add(0, 1); add(2, 3); add(4, 5); add(6, 7);
                add(0, 2); add(1, 3); add(4, 6); add(5, 7);
                add(0, 4); add(1, 5); add(2, 6); add(3, 7);
            }
        }
    }
#if defined(__GNUC__) && !defined(__clang__)
    if constexpr (Subset && std::is_trivially_copyable_v<T> && sizeof(T) <= 8) {
        if (n >= 32) {
            std::size_t half=8;
            for (;half<n/2;half*=4) {
                for (std::size_t base=0;base<n;base+=half*4) {
                    auto* a=f.data()+base;auto* b=a+half;auto* c=b+half;auto* d=c+half;
                    for (std::size_t j=0;j<half;j+=8) {
                        if constexpr (Subset) {
                            if constexpr(Subtract) b[j]-=a[j];else b[j]+=a[j];
                            if constexpr(Subtract) b[j+1]-=a[j+1];else b[j+1]+=a[j+1];
                            if constexpr(Subtract) b[j+2]-=a[j+2];else b[j+2]+=a[j+2];
                            if constexpr(Subtract) b[j+3]-=a[j+3];else b[j+3]+=a[j+3];
                            if constexpr(Subtract) b[j+4]-=a[j+4];else b[j+4]+=a[j+4];
                            if constexpr(Subtract) b[j+5]-=a[j+5];else b[j+5]+=a[j+5];
                            if constexpr(Subtract) b[j+6]-=a[j+6];else b[j+6]+=a[j+6];
                            if constexpr(Subtract) b[j+7]-=a[j+7];else b[j+7]+=a[j+7];
                            if constexpr(Subtract) d[j]-=c[j];else d[j]+=c[j];
                            if constexpr(Subtract) d[j+1]-=c[j+1];else d[j+1]+=c[j+1];
                            if constexpr(Subtract) d[j+2]-=c[j+2];else d[j+2]+=c[j+2];
                            if constexpr(Subtract) d[j+3]-=c[j+3];else d[j+3]+=c[j+3];
                            if constexpr(Subtract) d[j+4]-=c[j+4];else d[j+4]+=c[j+4];
                            if constexpr(Subtract) d[j+5]-=c[j+5];else d[j+5]+=c[j+5];
                            if constexpr(Subtract) d[j+6]-=c[j+6];else d[j+6]+=c[j+6];
                            if constexpr(Subtract) d[j+7]-=c[j+7];else d[j+7]+=c[j+7];
                            if constexpr(Subtract) c[j]-=a[j];else c[j]+=a[j];
                            if constexpr(Subtract) c[j+1]-=a[j+1];else c[j+1]+=a[j+1];
                            if constexpr(Subtract) c[j+2]-=a[j+2];else c[j+2]+=a[j+2];
                            if constexpr(Subtract) c[j+3]-=a[j+3];else c[j+3]+=a[j+3];
                            if constexpr(Subtract) c[j+4]-=a[j+4];else c[j+4]+=a[j+4];
                            if constexpr(Subtract) c[j+5]-=a[j+5];else c[j+5]+=a[j+5];
                            if constexpr(Subtract) c[j+6]-=a[j+6];else c[j+6]+=a[j+6];
                            if constexpr(Subtract) c[j+7]-=a[j+7];else c[j+7]+=a[j+7];
                            if constexpr(Subtract) d[j]-=b[j];else d[j]+=b[j];
                            if constexpr(Subtract) d[j+1]-=b[j+1];else d[j+1]+=b[j+1];
                            if constexpr(Subtract) d[j+2]-=b[j+2];else d[j+2]+=b[j+2];
                            if constexpr(Subtract) d[j+3]-=b[j+3];else d[j+3]+=b[j+3];
                            if constexpr(Subtract) d[j+4]-=b[j+4];else d[j+4]+=b[j+4];
                            if constexpr(Subtract) d[j+5]-=b[j+5];else d[j+5]+=b[j+5];
                            if constexpr(Subtract) d[j+6]-=b[j+6];else d[j+6]+=b[j+6];
                            if constexpr(Subtract) d[j+7]-=b[j+7];else d[j+7]+=b[j+7];
                        } else {
                            if constexpr(Subtract) a[j]-=b[j];else a[j]+=b[j];
                            if constexpr(Subtract) a[j+1]-=b[j+1];else a[j+1]+=b[j+1];
                            if constexpr(Subtract) a[j+2]-=b[j+2];else a[j+2]+=b[j+2];
                            if constexpr(Subtract) a[j+3]-=b[j+3];else a[j+3]+=b[j+3];
                            if constexpr(Subtract) a[j+4]-=b[j+4];else a[j+4]+=b[j+4];
                            if constexpr(Subtract) a[j+5]-=b[j+5];else a[j+5]+=b[j+5];
                            if constexpr(Subtract) a[j+6]-=b[j+6];else a[j+6]+=b[j+6];
                            if constexpr(Subtract) a[j+7]-=b[j+7];else a[j+7]+=b[j+7];
                            if constexpr(Subtract) c[j]-=d[j];else c[j]+=d[j];
                            if constexpr(Subtract) c[j+1]-=d[j+1];else c[j+1]+=d[j+1];
                            if constexpr(Subtract) c[j+2]-=d[j+2];else c[j+2]+=d[j+2];
                            if constexpr(Subtract) c[j+3]-=d[j+3];else c[j+3]+=d[j+3];
                            if constexpr(Subtract) c[j+4]-=d[j+4];else c[j+4]+=d[j+4];
                            if constexpr(Subtract) c[j+5]-=d[j+5];else c[j+5]+=d[j+5];
                            if constexpr(Subtract) c[j+6]-=d[j+6];else c[j+6]+=d[j+6];
                            if constexpr(Subtract) c[j+7]-=d[j+7];else c[j+7]+=d[j+7];
                            if constexpr(Subtract) a[j]-=c[j];else a[j]+=c[j];
                            if constexpr(Subtract) a[j+1]-=c[j+1];else a[j+1]+=c[j+1];
                            if constexpr(Subtract) a[j+2]-=c[j+2];else a[j+2]+=c[j+2];
                            if constexpr(Subtract) a[j+3]-=c[j+3];else a[j+3]+=c[j+3];
                            if constexpr(Subtract) a[j+4]-=c[j+4];else a[j+4]+=c[j+4];
                            if constexpr(Subtract) a[j+5]-=c[j+5];else a[j+5]+=c[j+5];
                            if constexpr(Subtract) a[j+6]-=c[j+6];else a[j+6]+=c[j+6];
                            if constexpr(Subtract) a[j+7]-=c[j+7];else a[j+7]+=c[j+7];
                            if constexpr(Subtract) b[j]-=d[j];else b[j]+=d[j];
                            if constexpr(Subtract) b[j+1]-=d[j+1];else b[j+1]+=d[j+1];
                            if constexpr(Subtract) b[j+2]-=d[j+2];else b[j+2]+=d[j+2];
                            if constexpr(Subtract) b[j+3]-=d[j+3];else b[j+3]+=d[j+3];
                            if constexpr(Subtract) b[j+4]-=d[j+4];else b[j+4]+=d[j+4];
                            if constexpr(Subtract) b[j+5]-=d[j+5];else b[j+5]+=d[j+5];
                            if constexpr(Subtract) b[j+6]-=d[j+6];else b[j+6]+=d[j+6];
                            if constexpr(Subtract) b[j+7]-=d[j+7];else b[j+7]+=d[j+7];
                        }
                    }
                }
            }
    for (; half < n; half *= 2) {
        for (std::size_t base = 0; base < n; base += half * 2) {
#if defined(__GNUC__) && !defined(__clang__)
            // 小さな単純型は8要素ずつ展開し、GCCの自動ベクトル化を促す。
            if constexpr (std::is_trivially_copyable_v<T> && sizeof(T) <= 8) {
                auto* out = f.data() + base + (Subset ? half : 0);
                auto* in = f.data() + base + (Subset ? 0 : half);
                std::size_t j = 0;
                for (; half - j >= 8; j += 8) {
