};
struct Generic {
    std::int64_t x=0; Generic()=default; explicit Generic(std::int64_t v):x(v){}
    Generic& operator+=(const Generic& b) { x+=b.x;return *this; }
    Generic& operator-=(const Generic& b) { x-=b.x;return *this; }
